import {
    CallExpressionShape,
    DurationShape,
    NumberShape,
    type ObjectShape,
    Plugin,
    Shape,
    StringShape,
    isGUID,
    type Diagnostics,
    type Factory,
    type Record,
    type RecordId,
} from '@servicenow/sdk-build-core'
import { NowIdShape } from '../now-id-plugin'
import { showGuidFieldDiagnostic } from '../utils'
import {
    CATEGORY_TABLE,
    METRIC_TABLE,
    DEFINITION_TABLE,
    DEFAULT_EVALUATION_METHOD,
    DEFAULT_ASSESSMENT_DURATION,
    DEFAULT_PUBLISH_STATE,
    orderValue,
    categoryToShape,
    createCategoryRecord,
    validatePublishState,
    baseAssessmentTypeProperties,
    baseAssessmentTypeToShapeProperties,
    withEncodedQueryTerminator,
} from './assessment-utils'

const ASSESSMENT_CALLEE = 'Assessment'
const TYPE_TABLE = 'asmt_metric_type'
const BUSINESS_RULE_TABLE = 'sys_script'
// Derives a stable symbolic key for the auto-created business rule from the assessment's
// own $id, so it gets a deterministic sys_id across rebuilds without requiring the
// developer to assign it a separate identifier.
const BUSINESS_RULE_KEY_SUFFIX = '__assessment_business_rule'
const DELETE_BUSINESS_RULE_KEY_SUFFIX = '__assessment_delete_business_rule'
const USER_FIELD_BUSINESS_RULE_KEY_SUFFIX = '__assessment_user_field_business_rule'
const BUSINESS_RULE_ORDER = 100
// Runs after the trigger/delete rules (order 100) so category-user updates from a
// userField change don't race the assessment-instance generation those perform.
const USER_FIELD_BUSINESS_RULE_ORDER = 300
const SCRIPT_METHODS = ['script', 'defaultAnswerFromScript']

const SCHEDULE_JOB_TABLE = 'sys_trigger'
const SCHEDULE_JOB_KEY_SUFFIX = '__assessment_schedule_job'
// Out-of-box ServiceNow system record for the generic "Run a script" job class
// (sys_job). This record ships with the platform and is stable across instances —
// Fluent references it, but never creates or owns it.
const RUN_SCRIPT_JOB_ID = '81c92ce9c0a8016400e5f0d2f784ea78'
const SCHEDULE_JOB_TRIGGER_TYPE = 2
const SCHEDULE_JOB_PRIORITY = 100
// Fixed platform label — every scheduled assessment's job shares this same name and
// classification, regardless of the assessment's own name.
const SCHEDULE_JOB_NAME = 'Scheduled type Assessment Creation'
const SCHEDULE_JOB_CLASSIFICATION = `On Demand.${SCHEDULE_JOB_NAME}`

// Escapes a value for embedding inside a single-quoted string literal in generated script.
function escapeScriptLiteral(value: string): string {
    return value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")
}

function buildAssessmentBusinessRuleScript(condition: string, assessmentSysId: string): string {
    const encodedQuery = escapeScriptLiteral(withEncodedQueryTerminator(condition))
    return `function onAfter(current, previous) {
    var AssessmentUtils = new global.AssessmentUtils();
    if (AssessmentUtils.conditionCheck(current, '${encodedQuery}')) {
        AssessmentUtils.checkRecord(current, '${assessmentSysId}', true);
    }
}`
}

function buildAssessmentScheduleScript(assessmentSysId: string): string {
    return `(new SNC.AssessmentCreation()).createAssessments('${assessmentSysId}');`
}

/**
 * Advanced (script) condition for the user-field business rule — evaluates true only
 * when `userField` (e.g. `assigned_to`) changed on the assessed record. Written to the
 * rule's own `condition` field, so unlike the trigger/delete rules, the rule's `script`
 * doesn't need to re-check it.
 */
function buildUserFieldBusinessRuleCondition(userField: string): string {
    const field = escapeScriptLiteral(userField)
    return `(new global.AssessmentUtils().conditionCheck(current, '${field}VALCHANGES^EQ'))`
}

/**
 * Script for the user-field business rule — propagates a `userField` change on an
 * assessed record to the category-user assignment of its already-generated assessable
 * records.
 */
function buildUserFieldBusinessRuleScript(userField: string, assessmentSysId: string): string {
    const field = escapeScriptLiteral(userField)
    return `function onAfter() {
    var asmtUtil = new global.AssessmentUtils();
    asmtUtil.updateAssessableRecordCategoryUser(current.getUniqueValue(), '${assessmentSysId}', previous.getValue('${field}'), current.getValue('${field}'));
}`
}

/**
 * Creates the `sys_trigger` job that regenerates assessment instances on a recurring
 * basis when `scheduleType: 'scheduled'`. Modeled directly on a platform-generated
 * trigger: `job_id` always points at the built-in "RunScriptJob" job class, `trigger_type`
 * is the fixed "Interval" code, and unused audit/runtime fields (`next_action`,
 * `run_count`, `sys_created_*`, ...) are left out entirely — those are computed by the
 * platform scheduler, not authored.
 */
async function createScheduleJobRecord(
    factory: Factory,
    callExpression: CallExpressionShape,
    options: { explicitId: string; assessmentSysId: string }
): Promise<Record> {
    const scriptShape = Shape.from(callExpression, buildAssessmentScheduleScript(options.assessmentSysId))
        .asString()
        .withContentType('cdata')

    return factory.createRecord({
        source: callExpression,
        table: SCHEDULE_JOB_TABLE,
        explicitId: options.explicitId,
        properties: {
            name: SCHEDULE_JOB_NAME,
            job_classification: SCHEDULE_JOB_CLASSIFICATION,
            // Fixed OOB sys_job record ("RunScriptJob") — referenced directly by sys_id,
            // never created or owned by Fluent.
            job_id: RUN_SCRIPT_JOB_ID,
            trigger_type: SCHEDULE_JOB_TRIGGER_TYPE,
            trigger_class: 'DEFAULT',
            state: 0,
            priority: SCHEDULE_JOB_PRIORITY,
            script: scriptShape,
        },
    })
}

/**
 * Creates a `sys_script` business rule backing a scored assessment (the trigger rule,
 * the delete rule, or the user-field rule). All three share an identical record
 * structure and field values (priority, access, etc.) and differ only in the fields
 * passed via `options` (name, `when`, `order`, an optional advanced `condition`, action
 * flags, description, and script). Surveys get no business rule; their `table` and
 * `condition` fields on `asmt_metric_type` are set directly instead.
 */
async function createBusinessRuleRecord(
    factory: Factory,
    callExpression: CallExpressionShape,
    options: {
        explicitId: string
        name: string
        collection: Shape
        when: 'before' | 'after'
        order?: number
        condition?: string
        actions: { action_insert?: boolean; action_update?: boolean; action_delete?: boolean }
        description: string
        script: string
    }
): Promise<Record> {
    const scriptShape = Shape.from(callExpression, options.script).asString().withContentType('cdata')
    const order = options.order ?? BUSINESS_RULE_ORDER

    return factory.createRecord({
        source: callExpression,
        table: BUSINESS_RULE_TABLE,
        explicitId: options.explicitId,
        properties: {
            name: options.name,
            collection: options.collection,
            when: options.when,
            active: true,
            order,
            ...options.actions,
            description: options.description,
            advanced: true,
            execute_function: true,
            ...(options.condition !== undefined ? { condition: options.condition } : {}),
            script: scriptShape,
            priority: order,
            access: 'package_private',
        },
    })
}

/**
 * `table` and `scaleFactor` are only mandatory when `evaluationMethod` is
 * `'assessment'` (the default) — a requirement the `evaluationMethod?: 'assessment'
 * | 'survey'` type can't express on its own, since omitting `evaluationMethod`
 * still implies `'assessment'`.
 */
function validateEvaluationMethod(arg: ObjectShape, diagnostics: Diagnostics): void {
    const evaluationMethod = arg.get('evaluationMethod').ifString()?.getValue() ?? DEFAULT_EVALUATION_METHOD
    if (evaluationMethod !== DEFAULT_EVALUATION_METHOD) {
        return
    }

    const tableShape = arg.get('table')
    if (!tableShape.ifString()?.ifNotEmpty()) {
        diagnostics.error(tableShape, "'table' is required when 'evaluationMethod' is 'assessment' (the default).")
    }

    const scaleFactorShape = arg.get('scaleFactor')
    const scaleFactorValue = scaleFactorShape.ifNumber()?.getValue()
    if (scaleFactorValue === undefined) {
        diagnostics.error(
            scaleFactorShape,
            "'scaleFactor' is required when 'evaluationMethod' is 'assessment' (the default)."
        )
    } else if (!Number.isInteger(scaleFactorValue)) {
        diagnostics.error(scaleFactorShape, "'scaleFactor' must be an integer.")
    }
}

/**
 * Cross-field validations the TypeScript types cannot express. Runs once per
 * assessment over every nested metric.
 */
function validateMetrics(arg: Shape, diagnostics: Diagnostics): void {
    const categories = arg.asObject().get('categories')?.ifArray()?.getElements() ?? []
    for (const categoryShape of categories) {
        const metrics = categoryShape.asObject().get('metrics').ifArray()?.getElements() ?? []
        for (const metricShape of metrics) {
            const metric = metricShape.asObject()

            // Note: the `reference` ⇒ `referenceTable` requirement is now enforced by the
            // MetricConfig discriminated union type, so no runtime diagnostic is needed.
            const scriptShape = metric.get('script')
            const script = scriptShape.ifString()?.ifNotEmpty()?.getValue()
            const method = metric.get('method').ifString()?.getValue()
            if (script && method && !SCRIPT_METHODS.includes(method)) {
                diagnostics.hint(
                    scriptShape,
                    "'script' is only evaluated when 'method' is 'script' or 'condscript'; it will be ignored otherwise."
                )
            }

            if (method === 'defaultAnswerFromScript') {
                const dependentPluginShape = metric.get('dependentPlugin')
                const dependentPlugin = dependentPluginShape.ifString()?.ifNotEmpty()?.getValue()
                if (!dependentPlugin) {
                    diagnostics.error(
                        dependentPluginShape,
                        "A metric with method 'condscript' must also set 'dependentPlugin'."
                    )
                }

                if (!script) {
                    diagnostics.error(scriptShape, "A metric with method 'condscript' must also set 'script'.")
                }
            }
        }
    }
}

/**
 * Reads a `businessRule`/`deleteBusinessRule`/`scheduleJob`/`userFieldBusinessRule`-style
 * field that is expected to hold either nothing (a new record will be generated) or an
 * existing record's sys_id.
 * Reports a diagnostic and returns `undefined` if a non-empty value is present but isn't a
 * valid GUID, so a typo or hand-authored garbage string can never end up as a dangling
 * reference in the generated XML.
 */
function readExistingGuidField(
    arg: ObjectShape,
    fieldName: string,
    tableName: string,
    diagnostics: Diagnostics
): string | undefined {
    const fieldShape = arg.get(fieldName).ifString()
    const value = fieldShape?.getValue()

    // Omitted or explicitly '' both mean "not set yet" - treat identically so a
    // blank value doesn't get flagged as an invalid GUID.
    if (value === undefined || value === '') {
        return undefined
    }

    if (!isGUID(value)) {
        showGuidFieldDiagnostic(fieldShape, fieldName, tableName, diagnostics)
        return undefined
    }
    return value
}

export const AssessmentPlugin = Plugin.create({
    name: 'AssessmentPlugin',

    records: {
        [TYPE_TABLE]: {
            relationships: {
                [CATEGORY_TABLE]: {
                    via: 'metric_type',
                    descendant: true,
                    relationships: {
                        [METRIC_TABLE]: {
                            via: 'category',
                            descendant: true,
                            relationships: {
                                [DEFINITION_TABLE]: {
                                    via: 'metric',
                                    descendant: true,
                                },
                            },
                        },
                    },
                },
                // `business_rule`, `delete_business_rule`, and `user_field_business_rule`
                // are separate reference columns on asmt_metric_type that each point at
                // their own auto-generated sys_script record (the trigger rule, the delete
                // rule, and the user-field rule). All three are inverse relationships - the
                // parent holds the FK, not the child - and all are descendants, so the
                // business rules are treated as part of the Assessment entity instead of
                // being independently transformed into standalone BusinessRule() calls.
                [BUSINESS_RULE_TABLE]: [
                    { via: 'business_rule', inverse: true, descendant: true },
                    { via: 'delete_business_rule', inverse: true, descendant: true },
                    { via: 'user_field_business_rule', inverse: true, descendant: true },
                ],
            },

            async toShape(record, { descendants, transform }) {
                const categories = descendants.query(CATEGORY_TABLE).sort((a, b) => orderValue(a) - orderValue(b))
                const metrics = descendants.query(METRIC_TABLE)
                const definitions = descendants.query(DEFINITION_TABLE)
                const isSurvey = record.get('evaluation_method').ifString()?.getValue() === 'survey'

                const categoryShapes = await Promise.all(
                    categories.map((category) => categoryToShape(category, metrics, definitions, transform))
                )

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: record,
                        callee: ASSESSMENT_CALLEE,
                        args: [
                            record.transform(({ $ }) => ({
                                ...baseAssessmentTypeToShapeProperties($, record),
                                table: $.from('table').def(''),
                                // Surveys don't target a table — suppress the internally-managed
                                // table and condition values so they don't appear in Fluent output.
                                ...(isSurvey ? { table: $.val('').def(''), condition: $.val('').def('') } : {}),
                                evaluationMethod: $.from('evaluation_method').def(DEFAULT_EVALUATION_METHOD),
                                assessmentDuration: $.from('duration')
                                    .map((v) => {
                                        const stringShape = v.ifString()?.ifNotEmpty()
                                        if (!stringShape) {
                                            return DurationShape.zero(record).getDuration()
                                        }
                                        return DurationShape.from(record, stringShape).getDuration()
                                    })
                                    .def(DurationShape.zero(record).getDuration()),
                                businessRule: $.from('business_rule').def(''),
                                deleteBusinessRule: $.from('delete_business_rule').def(''),
                                scheduleJob: $.from('job').def(''),
                                userFieldBusinessRule: $.from('user_field_business_rule').def(''),
                                categories: $.val(categoryShapes).def([]),
                            })),
                        ],
                    }),
                }
            },
        },
        [DEFINITION_TABLE]: {
            coalesce: ['metric', 'value'],
        },
    },

    shapes: [
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],
            async toRecord(callExpression, { factory, diagnostics }) {
                if (callExpression.getCallee() !== ASSESSMENT_CALLEE) {
                    return { success: false }
                }

                const arg = callExpression.getArgument(0).asObject()

                // Semantic validation that the type system cannot express.
                validateEvaluationMethod(arg, diagnostics)
                validatePublishState(arg, diagnostics)
                validateMetrics(arg, diagnostics)

                const isScoredAssessment =
                    (arg.get('evaluationMethod').ifString()?.getValue() ?? DEFAULT_EVALUATION_METHOD) ===
                    DEFAULT_EVALUATION_METHOD
                const isScheduled = arg.get('scheduleType').ifString()?.getValue() === 'scheduled'
                const userField = arg.get('userField').ifString()?.ifNotEmpty()?.getValue() ?? ''
                const state = arg.get('state').ifString()?.getValue() ?? DEFAULT_PUBLISH_STATE
                // The user-field business rule only makes sense for a scored, scheduled,
                // published assessment that actually names a userField to watch.
                const shouldGenerateUserFieldBusinessRule =
                    isScoredAssessment && isScheduled && userField !== '' && state === 'published'

                // Only scheduled assessments get an auto-generated recurring job. Prefer an
                // existing job sys_id (from XML import / bi-di sync) over an auto-derived key,
                // same as the business rules below, so re-running the build doesn't create a
                // second job alongside one the platform (or a prior build) already created.
                let scheduleJobKey: string | undefined
                let scheduleJobRef: RecordId | undefined
                // True only when we're minting a brand-new schedule job; false when an
                // existing sys_id was supplied, in which case we leave that record alone
                // instead of re-authoring it on every build.
                let isNewScheduleJob = false
                if (isScheduled) {
                    const existingScheduleJob = readExistingGuidField(
                        arg,
                        'scheduleJob',
                        SCHEDULE_JOB_TABLE,
                        diagnostics
                    )
                    isNewScheduleJob = !existingScheduleJob
                    scheduleJobKey =
                        existingScheduleJob ??
                        `${arg.get('$id').as([NowIdShape, StringShape, NumberShape]).getValue()}${SCHEDULE_JOB_KEY_SUFFIX}`
                    scheduleJobRef = await factory.createReference({
                        source: callExpression,
                        table: SCHEDULE_JOB_TABLE,
                        guid: scheduleJobKey,
                    })
                }

                // Only scored assessments get auto-generated business rules.
                let businessRuleKey: string | undefined
                let businessRuleRef: RecordId | undefined
                let deleteBusinessRuleKey: string | undefined
                let deleteBusinessRuleRef: RecordId | undefined
                // Same idea as isNewScheduleJob above, for each business rule.
                let isNewBusinessRule = false
                let isNewDeleteBusinessRule = false
                if (isScoredAssessment) {
                    // Always author the business rules with an auto-derived key so the
                    // same records are (re)created deterministically on every build.
                    isNewBusinessRule = true
                    businessRuleKey = `${arg.get('$id').as([NowIdShape, StringShape, NumberShape]).getValue()}${BUSINESS_RULE_KEY_SUFFIX}`
                    businessRuleRef = await factory.createReference({
                        source: callExpression,
                        table: BUSINESS_RULE_TABLE,
                        guid: businessRuleKey,
                    })
                    isNewDeleteBusinessRule = true
                    deleteBusinessRuleKey = `${arg.get('$id').as([NowIdShape, StringShape, NumberShape]).getValue()}${DELETE_BUSINESS_RULE_KEY_SUFFIX}`
                    deleteBusinessRuleRef = await factory.createReference({
                        source: callExpression,
                        table: BUSINESS_RULE_TABLE,
                        guid: deleteBusinessRuleKey,
                    })
                }

                // Same idea as the business rules above, gated by shouldGenerateUserFieldBusinessRule.
                let userFieldBusinessRuleKey: string | undefined
                let userFieldBusinessRuleRef: RecordId | undefined
                let isNewUserFieldBusinessRule = false
                if (shouldGenerateUserFieldBusinessRule) {
                    const existingUserFieldBusinessRule = readExistingGuidField(
                        arg,
                        'userFieldBusinessRule',
                        BUSINESS_RULE_TABLE,
                        diagnostics
                    )
                    isNewUserFieldBusinessRule = !existingUserFieldBusinessRule
                    userFieldBusinessRuleKey =
                        existingUserFieldBusinessRule ??
                        `${arg.get('$id').as([NowIdShape, StringShape, NumberShape]).getValue()}${USER_FIELD_BUSINESS_RULE_KEY_SUFFIX}`
                    userFieldBusinessRuleRef = await factory.createReference({
                        source: callExpression,
                        table: BUSINESS_RULE_TABLE,
                        guid: userFieldBusinessRuleKey,
                    })
                }

                const typeRecord = await factory.createRecord({
                    source: callExpression,
                    table: TYPE_TABLE,
                    explicitId: arg.get('$id'),
                    properties: arg.transform(({ $ }) => ({
                        sys_domain: $.val('global'),
                        sys_domain_path: $.val('/'),
                        disable_ui_action: $.def(''),
                        enable_ui_action: $.def(''),
                        job: isScheduled ? $.val(scheduleJobRef!) : $.def(''),
                        user_field_business_rule: shouldGenerateUserFieldBusinessRule
                            ? $.val(userFieldBusinessRuleRef!)
                            : $.def(''),
                        business_rule: isScoredAssessment ? $.val(businessRuleRef!) : $.def(''),
                        delete_business_rule: isScoredAssessment ? $.val(deleteBusinessRuleRef!) : $.def(''),
                        ...baseAssessmentTypeProperties($),
                        filter_table: $.from('table').def(''),
                        evaluation_method: $.from('evaluationMethod').def(DEFAULT_EVALUATION_METHOD),
                        duration: $.from('assessmentDuration')
                            .map((v) => {
                                // Omitted -> let .def() supply DEFAULT_ASSESSMENT_DURATION.
                                if (!v.isDefined()) {
                                    return undefined
                                }
                                // assessmentDuration may be a Duration() helper call, a plain
                                // duration object, or a glide_duration string.
                                if (v.is(DurationShape)) {
                                    return v.as(DurationShape).toString().getValue()
                                }
                                const source = v.ifObject() ?? v.asString()
                                return DurationShape.from(v.getSource(), source).toString().getValue()
                            })
                            .def(DEFAULT_ASSESSMENT_DURATION),
                    })),
                })

                // For surveys, set `table` and `condition` directly on the type record
                // instead of creating a separate business rule.
                const finalTypeRecord = isScoredAssessment
                    ? typeRecord
                    : (typeRecord.merge({
                          table: TYPE_TABLE,
                          condition: withEncodedQueryTerminator(`sys_id=${typeRecord.getId().getValue()}`),
                      }) as Record)

                const categories = arg.get('categories')?.ifArray()?.getElements() ?? []
                const tableForCategories =
                    arg.get('table').ifString()?.ifNotEmpty() ?? Shape.from(callExpression, TYPE_TABLE).asString()
                const categoryRecords = await Promise.all(
                    categories.map((category) =>
                        createCategoryRecord(
                            category,
                            finalTypeRecord,
                            tableForCategories,
                            factory,
                            callExpression,
                            diagnostics
                        )
                    )
                )

                const name = arg.get('name').ifString()?.getValue() ?? ''
                const assessmentSysId = finalTypeRecord.getId().getValue()

                const generatedRecords: Record[] = []

                if (isScoredAssessment) {
                    const condition = arg.get('condition').ifString()?.getValue() ?? ''
                    const collection = arg.get('table')

                    // Trigger rule: runs after insert/update and generates the assessment
                    // when the assessment's condition matches. Only (re)authored when it's
                    // newly minted here — an existing sys_id (from XML import / bi-di sync)
                    // is left untouched so manual edits on the instance aren't clobbered.
                    if (isNewBusinessRule) {
                        generatedRecords.push(
                            await createBusinessRuleRecord(factory, callExpression, {
                                explicitId: businessRuleKey!,
                                name: `${name} Assessment Trigger`,
                                collection,
                                when: 'after',
                                actions: { action_insert: true, action_update: true },
                                description: `Auto-generated by the '${name}' assessment. Triggers assessment generation when the assessment's condition matches.`,
                                script: buildAssessmentBusinessRuleScript(condition, assessmentSysId),
                            })
                        )
                    }
                    // Delete rule: runs before delete and cleans up assessment instances
                    // when the source record is deleted. Same "only if new" rule as above.
                    if (isNewDeleteBusinessRule) {
                        generatedRecords.push(
                            await createBusinessRuleRecord(factory, callExpression, {
                                explicitId: deleteBusinessRuleKey!,
                                name: `${name} Assessment Delete`,
                                collection,
                                when: 'before',
                                actions: { action_delete: true },
                                description: `Auto-generated by the '${name}' assessment. Cleans up assessment instances when the source record is deleted.`,
                                script: `function onBefore(current, previous) {
    new global.AssessmentUtils().checkDeleteRecord(current, '${assessmentSysId}', true);
}`,
                            })
                        )
                    }

                    // User-field rule: runs after update, gated by an advanced condition that
                    // only matches when userField itself changed, and propagates that change
                    // to the category-user assignment of already-generated assessable records.
                    // Only for a scored, scheduled, published assessment with a userField set.
                    if (shouldGenerateUserFieldBusinessRule && isNewUserFieldBusinessRule) {
                        generatedRecords.push(
                            await createBusinessRuleRecord(factory, callExpression, {
                                explicitId: userFieldBusinessRuleKey!,
                                name: `${name} Assessment User Field Update`,
                                collection,
                                when: 'after',
                                order: USER_FIELD_BUSINESS_RULE_ORDER,
                                condition: buildUserFieldBusinessRuleCondition(userField),
                                actions: { action_update: true },
                                description: `Auto-generated by the '${name}' assessment. Updates assessable record category ownership when '${userField}' changes.`,
                                script: buildUserFieldBusinessRuleScript(userField, assessmentSysId),
                            })
                        )
                    }
                }

                if (isScheduled && isNewScheduleJob) {
                    generatedRecords.push(
                        await createScheduleJobRecord(factory, callExpression, {
                            explicitId: scheduleJobKey!,
                            assessmentSysId,
                        })
                    )
                }

                return {
                    success: true,
                    value: finalTypeRecord.with(...categoryRecords, ...generatedRecords),
                }
            },
        },
    ],
})
